def parse_duration(s):
    if not s:
        return None
    try:
        parts = s.lower().replace(' ', '').split('h')
        hours = int(parts[0]) * 3600 if parts[0] else 0
        minutes = int(parts[1].replace('m', '')) * 60 if 'm' in s else 0
        seconds = int(parts[1].replace('m', '')) if 'h' not in s else 0
        return hours + minutes + seconds
    except ValueError:
        return None
